import { Kafka, Producer } from 'kafkajs';

const kafka = new Kafka({
  clientId: 'event-ingestion-service',
  brokers: ['broker-1:9092', 'broker-2:9092', 'broker-3:9092'],
});

const producer: Producer = kafka.producer();

// Topic 'account-events' is provisioned with 12 partitions, consumed by
// a matching 12-consumer group (see consumer-group.ts).
const TOPIC = 'account-events';

// Only ~5 distinct country codes exist across our account base, and traffic
// is heavily skewed: the vast majority of accounts are 'US'.
type CountryCode = 'US' | 'GB' | 'DE' | 'IN' | 'BR';

interface AccountEvent {
  accountId: string; // UUID, high cardinality
  countryCode: CountryCode; // low cardinality, skewed toward 'US'
  eventType: 'login' | 'purchase' | 'profile_update' | 'logout';
  payload: Record<string, unknown>;
}

async function connect(): Promise<void> {
  await producer.connect();
}

/**
 * Publishes an account event to the account-events topic.
 *
 * The message key is set to countryCode to keep events ordered --
 * Kafka guarantees ordering only for messages sharing the same key,
 * so every event for a given key lands on the same partition in the
 * order it was produced.
 */
async function publishEvent(event: AccountEvent): Promise<void> {
  await producer.send({
    topic: TOPIC,
    messages: [
      {
        key: event.countryCode,
        value: JSON.stringify(event),
      },
    ],
  });
}

function randomAccountId(): string {
  return `acct-${Math.random().toString(36).slice(2, 10)}`;
}

// Skewed distribution: 'US' dominates, matching real production traffic.
function pickCountryCode(): CountryCode {
  const roll = Math.random();
  if (roll < 0.9) return 'US';
  if (roll < 0.93) return 'GB';
  if (roll < 0.96) return 'DE';
  if (roll < 0.98) return 'IN';
  return 'BR';
}

const EVENT_TYPES: AccountEvent['eventType'][] = [
  'login',
  'purchase',
  'profile_update',
  'logout',
];

async function runLoad(totalEvents: number): Promise<void> {
  await connect();

  for (let i = 0; i < totalEvents; i++) {
    const event: AccountEvent = {
      accountId: randomAccountId(),
      countryCode: pickCountryCode(),
      eventType: EVENT_TYPES[Math.floor(Math.random() * EVENT_TYPES.length)],
      payload: { seq: i, ts: Date.now() },
    };

    await publishEvent(event);
  }

  await producer.disconnect();
}

runLoad(200_000).catch((err) => {
  console.error('event-ingestion producer failed', err);
  process.exit(1);
});
